@staticmethod
def mode(numbers):
    """Find the most common number in a list."""
    if not numbers:
        raise ValueError("Cannot find mode of empty list")

    frequency = {}
    for num in numbers:
        frequency[num] = frequency.get(num, 0) + 1

    max_count = max(frequency.values())
    modes = [k for k, v in frequency.items() if v == max_count]
    return modes[0]

