@staticmethod
def mode(numbers: List[Union[int, float]]) -> Union[List[Union[int, float]], None]:
    """Find the most common number(s) in a list.

    Returns all values that appear with maximum frequency.
    If no duplicates exist, returns None.
    """
    if not numbers:
        raise ValueError("Cannot find mode of empty list")

    frequency = {}
    for num in numbers:
        frequency[num] = frequency.get(num, 0) + 1

    max_count = max(frequency.values())
    modes = [k for k, v in frequency.items() if v == max_count]

    # Return all modes if there are ties, otherwise return the single mode
    return modes if len(modes) > 1 else modes[0]

def _load_data(self) -> None:
    """Load data from CSV file into memory.

    Raises:
        FileNotFoundError: If the specified file does not exist
        ValueError: If the file is empty or malformed
    """
    try:
        with open(self.filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)

            if not reader.fieldnames:
                raise ValueError("CSV file has no headers")

            self.headers = list(reader.fieldnames)

            for row_num, row in enumerate(reader, start=2):
                # Skip empty rows
                if any(row.values()):  # At least one non-empty value
                    self.data.append(dict(row))
    except FileNotFoundError:
        raise FileNotFoundError(f"CSV file not found: {self.filepath}")
    except csv.Error as e:
        raise ValueError(f"Error parsing CSV file '{self.filepath}': {e}")

