def generate_grouped_report(self, group_column, target_column, output_path=None):
    """Generate a report grouped by a specific column."""
    groups = self.processor.aggregate(group_column, target_column, "sum")

    report = {
        "group_by": group_column,
        "target": target_column,
        "group_totals": groups,
        "overall_total": sum(groups.values()),
        "group_count": len(groups),
    }

    if output_path:
        self._save_report(report, output_path)

    return report

def generate_trend_report(self, date_column, value_column, start_date, end_date):
    """Generate a trend report over a date range."""
    self.processor.filter_by_date(date_column, start_date, end_date)

    values = self._extract_numeric_values(value_column)

    if len(values) < 2:
        return {"error": "Insufficient data for trend analysis"}

    return {
        "period": f"{start_date} to {end_date}",
        "total": sum(values),
        "average": self.calculator.mean(values),
        "data_points": len(values),
        "growth_rate": self._calculate_growth_rate(values),
    }

def compare_groups(self, group_column, target_column, group_a, group_b):
    """Compare statistical properties between two groups."""
    all_rows = self.processor.get_rows()

    values_a = [
        float(row[target_column]) for row in all_rows
        if row.get(group_column) == group_a
    ]
    values_b = [
        float(row[target_column]) for row in all_rows
        if row.get(group_column) == group_b
    ]

    if not values_a or not values_b:
        return {"error": "One or both groups have no data"}

    return {
        "group_a": {
            "name": group_a,
            "count": len(values_a),
            "mean": self.calculator.mean(values_a),
            "std_dev": self.calculator.std_dev(values_a),
        },
        "group_b": {
            "name": group_b,
            "count": len(values_b),
            "mean": self.calculator.mean(values_b),
            "std_dev": self.calculator.std_dev(values_b),
        },
        "difference_in_means": self.calculator.mean(values_a) - self.calculator.mean(values_b),
    }

def rank_categories(self, category_column, value_column, top_n=5):
    """Rank categories by their total values."""
    aggregation = self.processor.aggregate(category_column, value_column, "sum")

    sorted_cats = sorted(aggregation.items(), key=lambda x: x[1], reverse=True)

    return {
        "rankings": sorted_cats[:top_n],
        "total_categories": len(aggregation),
    }

def _save_report(self, report, output_path):
    """Save report to a text file."""
    with open(output_path, 'w') as f:
        f.write("=== Report ===\n\n")
        for key, value in report.items():
            f.write(f"{key}: {value}\n")

