def aggregate(self, group_by: str, agg_column: str, func: str = "sum") -> Dict[str, Union[int, float]]:
    """Aggregate data by grouping column.

    Args:
        group_by: Column name to group by
        agg_column: Column name to aggregate
        func: Aggregation function ('sum', 'count', 'avg', 'max', 'min')

    Returns:
        Dictionary mapping group keys to aggregated values
    """
    groups = {}
    for row in self.data:
        key = row.get(group_by)
        if key is None:
            continue  # Skip rows with missing group key

        value_str = row.get(agg_column, "")
        try:
            value = float(value_str) if value_str else 0.0
        except (ValueError, TypeError):
            continue  # Skip rows with non-numeric values in aggregation column

        if key not in groups:
            groups[key] = []
        groups[key].append(value)

    results = {}
    for key, values in groups.items():
        if func == "sum":
            results[key] = sum(values)
        elif func == "count":
            results[key] = len(values)
        elif func == "avg":
            results[key] = sum(values) / len(values) if values else 0.0
        elif func == "max":
            results[key] = max(values) if values else 0.0
        elif func == "min":
            results[key] = min(values) if values else 0.0

    return results

